  'aiConsent.badge': 'BEVOR DU STARTEST',
  'aiConsent.title': 'KI-Funktionen senden Nachrichten von deinem Gerät weg',
  'aiConsent.lead':
    'Chatterbox verschlüsselt deine Nachrichten, sodass nur du und die andere Person sie lesen können. KI ist die einzige Ausnahme, und sie benötigt deine Erlaubnis.',
  'aiConsent.point1': 'Zum Zusammenfassen, Übersetzen oder Transkribieren werden die ausgewählten Nachrichten auf diesem Gerät entschlüsselt und an unseren Server und dessen KI-Anbieter gesendet.',
  'aiConsent.point2': 'Sie werden gesendet, um dein Ergebnis zu erzeugen, nicht um etwas zu trainieren — aber während der Übertragung und Verarbeitung sind sie nicht Ende-zu-Ende-verschlüsselt.',
  'aiConsent.point3': 'Alles andere bleibt verschlüsselt: Nachrichten, auf die du keine KI anwendest, sowie deine geteilten Listen.',
  'aiConsent.revoke': 'Du kannst dies jederzeit unter Profil → KI-Funktionen deaktivieren. Es wird nichts gesendet, bevor du es erlaubst.',
  'aiConsent.accept': 'KI-Funktionen erlauben',
  'aiConsent.decline': 'Jetzt nicht',
  'aiConsent.settingsTitle': 'KI-Funktionen',
  'aiConsent.settingsOn': 'Erlaubt — ausgewählte Nachrichten werden von diesem Gerät gesendet, wenn du KI verwendest.',
  'aiConsent.settingsOff': 'Aus — es wird nichts gesendet. Du wirst gefragt, bevor eine KI-Funktion ausgeführt wird.',
  'aiConsent.turnOff': 'KI-Funktionen deaktivieren',
  'aiConsent.turnOn': 'KI-Funktionen erlauben',
  'aiConsent.turnedOff': 'KI-Funktionen auf diesem Gerät deaktiviert',
  'signals.typingTitle': 'Tippanzeigen',
  'signals.typingOn': 'An — der Server speichert, wann du schreibst, und du siehst, wann die andere Person schreibt.',
  'signals.typingOff': 'Aus — es wird nicht gespeichert, wann du schreibst, und du siehst nicht, wann die andere Person schreibt.',
  'signals.receiptsTitle': 'Lesebestätigungen',
  'signals.receiptsOn': 'An — der Server speichert, wann du eine Nachricht liest, und du siehst, wann die andere Person es getan hat.',
  'signals.receiptsOff': 'Aus — es wird nicht gespeichert, wann du liest, und du siehst nicht, wann die andere Person es getan hat.',
