  'aiConsent.point1': 'Özetleme, çeviri veya transkripsiyon için seçilen mesajların şifresi bu cihazda çözülür ve sunucumuza ve onun yapay zekâ sağlayıcısına gönderilir.',
  'aiConsent.point2': 'Herhangi bir şeyi eğitmek için değil, sonucunuzu üretmek için gönderilirler — ancak iletim ve işlem sırasında uçtan uca şifreli değildirler.',
  'aiConsent.point3': 'Geri kalan her şey şifreli kalır: yapay zekâ kullanmadığınız mesajlar ve paylaşılan listeleriniz.',
  'aiConsent.revoke': 'Bunu istediğiniz zaman Profil → Yapay zekâ özellikleri bölümünden kapatabilirsiniz. Siz izin vermeden hiçbir şey gönderilmez.',
