  'aiConsent.title': 'ویژگی‌های هوش مصنوعی پیام‌ها را از دستگاه شما خارج می‌کنند',
  'aiConsent.lead':
    'Chatterbox پیام‌های شما را رمزگذاری می‌کند تا فقط شما و طرف مقابل بتوانید آن‌ها را بخوانید. هوش مصنوعی تنها استثناست و به اجازهٔ شما نیاز دارد.',
  'aiConsent.point1': 'برای خلاصه‌سازی، ترجمه یا تبدیل گفتار به نوشتار، پیام‌های انتخاب‌شده روی این دستگاه رمزگشایی و به سرور ما و ارائه‌دهندهٔ هوش مصنوعی آن فرستاده می‌شوند.',
  'aiConsent.point2': 'این پیام‌ها برای تولید نتیجهٔ شما فرستاده می‌شوند، نه برای آموزش چیزی — اما در حین انتقال و پردازش، رمزگذاری سرتاسری ندارند.',
  'aiConsent.point3': 'بقیهٔ موارد رمزگذاری‌شده باقی می‌مانند: پیام‌هایی که روی آن‌ها از هوش مصنوعی استفاده نمی‌کنید، و فهرست‌های اشتراکی شما.',
  'aiConsent.revoke': 'می‌توانید این را هر زمان از نمایه ← ویژگی‌های هوش مصنوعی خاموش کنید. تا زمانی که اجازه ندهید، چیزی فرستاده نمی‌شود.',
