  'aiConsent.lead':
    'Chatterbox מצפין את ההודעות שלכם כך שרק אתם והצד השני יכולים לקרוא אותן. בינה מלאכותית היא היוצא מן הכלל היחיד, והיא דורשת את אישורכם.',
