  'aiConsent.point3': 'כל השאר נשאר מוצפן: הודעות שאינכם משתמשים בהן בבינה מלאכותית, והרשימות המשותפות שלכם.',
  'aiConsent.revoke': 'אפשר לכבות זאת בכל עת בפרופיל ← תכונות בינה מלאכותית. שום דבר לא נשלח עד שתאשרו.',
